import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Фильтр для фото меняет настроение снимка одним нажатием. Он сдвигает цвета, контраст и тон, превращая обычный снимок в стилизованную картинку.</p>\n<p>Фильтры — самая быстрая правка в фотографии. Одно касание может сделать фото винтажным, драматичным, тёплым или холодным без какой-либо ручной настройки.</p>\n<p>В этом руководстве мы расскажем, как работают фильтры, что делают 11 стилей и как пользоваться ими хорошо. Речь пойдёт об интенсивности, сравнении, единообразии и ошибках, из-за которых фото с фильтром выглядят дёшево. Примерить все 11 стилей на своём фото помогут <a href=\"/ru/filtry-dlya-izobrazhenii/\">Фильтры для изображений</a> — выберите стиль, настройте интенсивность и сохраните результат.</p>\n<h2 id=\"what-filters-do\">Что на самом деле делают фильтры для фото</h2>\n<p>Фильтр применяет к фото заранее заданное сочетание изменений цвета, контраста и тона. Каждый фильтр — это рецепт: более тёплые цвета, более мягкий контраст, выцветшие чёрные или более холодная палитра.</p>\n<p>Изменения происходят сразу все. Вместо того чтобы отдельно настраивать яркость, контраст и насыщенность, фильтр применяет согласованный набор изменений за один шаг.</p>\n<p>Фильтры не добавляют фото деталей. Они меняют то, как выглядят существующие детали, сдвигая настроение, не меняя объект или композицию.</p>\n<p>Думайте о фильтре как о тонированной линзе. Сцена остаётся прежней, но цвета и свет ощущаются иначе — будто фото сделано в другую эпоху или в другом месте.</p>\n<p>Фильтр — это готовый рецепт от фотографа, который его придумал: кто-то уже подобрал сочетание яркости, контраста и цвета за вас. Поэтому фильтр экономит время, но не заменяет понимание: если результат не нравится, знайте, что его всегда можно подправить ползунком интенсивности.</p>\n<h2 id=\"eleven-filter-styles\">11 стилей фильтров</h2>\n<p>Инструмент предлагает 11 стилей фильтров: «Чёрно-белый», «Сепия», «Винтаж», «Тёплый», «Холодный», «Высокий контраст», «Матовый», «Драматичный», «Ч/б Нуар», «Золотой час» и «Инверсия». Каждый из них даёт отчётливый вид.</p>\n<p>«Чёрно-белый» убирает весь цвет, делая фото чёрно-белым. «Ч/б Нуар» делает то же самое, но с более сильным контрастом, придавая драматичный чёрно-белый вид, похожий на плёнку.</p>\n<p>«Сепия» добавляет тёплый коричневый оттенок, который кажется старым и ностальгическим. «Винтаж» похож, но мягче: с выцветшими цветами и нежным плёночным видом.</p>\n<p>«Тёплый» добавляет золотистый оттенок, «Холодный» — синий, а «Золотой час» имитирует тёплый свет заката. «Высокий контраст» добавляет энергии, «Матовый» смягчает чёрный цвет, «Драматичный» углубляет тени, а «Инверсия» полностью переворачивает цвета.</p>\n<h2 id=\"filter-intensity\">Интенсивность фильтра: от 0% до 100%</h2>\n<p>Интенсивность управляет тем, насколько сильно применяется фильтр. При 100 процентах виден полный эффект, а при 0 процентах фото не меняется.</p>\n<p>Установка интенсивности ниже 100 процентов смешивает отфильтрованные пиксели обратно к оригиналу. Фильтр «Винтаж» на 45 процентах даёт лёгкую плёночную дымку, не подавляя естественные тона кожи.</p>\n<p>Более низкая интенсивность часто оказывается лучшим выбором. Фильтр на полной мощности может подавить фото, а тот же фильтр на 50 процентах добавляет настроение, не скрывая объект.</p>\n<p>Сначала попробуйте фильтр на 100 процентах, чтобы увидеть его характер, затем уменьшайте интенсивность, пока эффект не станет правильным. Предпросмотр обновляется вживую, поэтому найти золотую середину можно быстро.</p>\n<p>Удобный приём — «правило половины»: какой бы фильтр вы ни выбрали, сначала поставьте его на 50 процентов. В половине случаев этого уже достаточно, а если мало — поднимайте постепенно, пока настроение не станет именно таким, как задумано.</p>\n<h2 id=\"vintage-default\">Почему «Винтаж» выбран по умолчанию</h2>\n<p>Инструмент выбирает «Винтаж» на 100 процентах сразу, как только вы перетаскиваете фото. Такое значение по умолчанию сразу даёт готовый эффект на основном холсте, и вы видите, на что способен фильтр.</p>\n<p>«Винтаж» — мягкий, лестный фильтр. Его выцветшие цвета и мягкий контраст подходят большинству фото, и он редко делает снимок хуже, что делает его безопасным вариантом по умолчанию.</p>\n<p>Нажмите на любую другую плитку в пресетах фильтров, чтобы переключиться, или нажмите «Сброс», чтобы вернуться к оригиналу. Значение по умолчанию — это отправная точка, а не обязательство.</p>\n<p>Если «Винтаж» не подходит вашему фото, попробуйте «Тёплый» или «Золотой час» для похожего ощущения с другими цветами. Три тёплых фильтра имеют общее настроение, но различаются по тону.</p>\n<h2 id=\"grayscale-vs-noir\">«Чёрно-белый» и «Ч/б Нуар»</h2>\n<p>«Чёрно-белый» убирает цвет и оставляет прямое чёрно-белое изображение. Оно чистое, нейтральное и честное: показывает фото ровно таким, какое оно есть, без цвета.</p>\n<p>«Ч/б Нуар» убирает цвет и добавляет сильный контраст. Чёрные становятся глубже, белые — ярче, а изображение приобретает драматичное качество, похожее на плёнку.</p>\n<p>Используйте «Чёрно-белый», когда фото должно казаться спокойным и документальным. Используйте «Ч/б Нуар», когда оно должно казаться драматичным, с сильными тенями и смелыми светами.</p>\n<p>Оба подходят архитектуре, уличной фотографии и портретам с сильными выражениями. Выбор зависит от того, хотите ли вы тихое или драматичное чёрно-белое фото.</p>\n<h2 id=\"sepia-vintage-matte-golden\">«Сепия», «Винтаж», «Матовый» и «Золотой час»</h2>\n<p>«Сепия» добавляет тёплый коричневый оттенок, который кажется старым. Она подходит историческим фото, семейным воспоминаниям и любому снимку, который должен казаться пришедшим из другой эпохи.</p>\n<p>«Винтаж» мягче «Сепии»: с выцветшими цветами и нежным плёночным видом. Он подходит повседневным фото и постам в соцсетях, где ностальгия должна казаться лёгкой, а не тяжёлой.</p>\n<p>«Матовый» смягчает чёрный цвет, придавая фото выцветшее качество, похожее на плёнку. Он подходит портретам и фото в стиле «лайфстайл», где хорошо работает мягкое, мечтательное ощущение.</p>\n<p>«Золотой час» имитирует тёплый свет заката. Он добавляет золотое свечение, которое подходит пейзажам, портретам и любому фото, снятому в тёплом свете.</p>\n<h2 id=\"warm-vs-cool\">«Тёплый» и «Холодный» фильтры</h2>\n<p>«Тёплый» добавляет золотистый, жёлтый оттенок, который кажется солнечным и располагающим. Он подходит портретам, еде и пейзажам, где тёплое свечение делает изображение гостеприимным.</p>\n<p>«Холодный» добавляет синий оттенок, который кажется спокойным и резким. Он подходит зимним сценам, архитектуре и технике, где холодная палитра кажется современной и чистой.</p>\n<p>Выбор зависит от настроения, которое вы хотите. Тёплый фильтр на снежной сцене кажется неправильным, а холодный фильтр на пляжном закате спорит с естественным теплом.</p>\n<p>Попробуйте оба на одном фото и сравните. Разница сразу очевидна, и правильный вариант обычно кажется принадлежащим сцене.</p>\n<p>Тёплый и холодный фильтры — это ещё и способ исправить свет при съёмке: фото, снятое в тени, часто само по себе холодное, и «Тёплый» возвращает ему жизнь, а снимок при жёлтом свете лампы, наоборот, спасает «Холодный».</p>\n<h2 id=\"invert-filter\">Фильтр «Инверсия»</h2>\n<p>«Инверсия» переворачивает каждый цвет в противоположный: чёрный становится белым, синий — оранжевым, а красный — голубым. Результат выглядит как фотографический негатив.</p>\n<p>«Инверсия» — самый необычный фильтр в наборе, и он подходит для узкого круга задач. Он работает для художественных эффектов, для проверки изображения и для создания яркой графики.</p>\n<p>Для большинства фото «Инверсия» — скорее новинка, чем практичная правка. Перевёрнутый портрет выглядит странно, а перевёрнутый пейзаж — чужеродно.</p>\n<p>Используйте «Инверсию» умеренно, для конкретной творческой цели. Одно перевёрнутое изображение в серии может быть ярким, а целая лента из них сбивает с толку.</p>\n<h2 id=\"hold-to-view-original\">«Удерживайте, чтобы увидеть оригинал»</h2>\n<p>Кнопка «Удерживайте, чтобы увидеть оригинал» показывает неотфильтрованное фото, пока вы её нажимаете. Отпустите её — и отфильтрованная версия вернётся.</p>\n<p>Это самый быстрый способ оценить фильтр. Нажмите и удерживайте, чтобы увидеть оригинал, отпустите, чтобы увидеть правку, — и разница станет сразу очевидной.</p>\n<p>Используйте её после каждого изменения фильтра. Фильтр, который хорошо выглядит сам по себе, рядом с оригиналом может выглядеть неправильно, а кнопка удержания делает сравнение мгновенным.</p>\n<p>Кнопка особенно полезна для тонких фильтров. Фильтр «Винтаж» на 45 процентах трудно оценить в одиночку, но сравнение при удержании точно показывает, что он изменил.</p>\n<p>Сделайте удержание привычкой после каждого фильтра: нажмите, отпустите, нажмите снова. Если с третьего раза разница уже не бросается в глаза, фильтр, скорее всего, слишком слабый — усильте его или выберите другой.</p>\n<h2 id=\"side-by-side-compare\">Сравнение рядом</h2>\n<p>Инструмент также предлагает разделённое сравнение рядом, показывая оригинал и отфильтрованную версию друг рядом с другом. Это лучший способ внимательно оценить фильтр.</p>\n<p>Разделённый вид точно показывает, какие области изменились и насколько. Кожа, небо и тени видны в обеих версиях одновременно.</p>\n<p>Используйте разделённый вид при выборе между двумя фильтрами. Примените один, проверьте разделённый вид, затем примените другой и сравните снова. Лучший фильтр обычно очевиден.</p>\n<p>Для итоговой проверки используйте полноэкранное сравнение. Большой вид показывает детали, которые скрывает маленький предпросмотр, включая тонкие сдвиги цвета на коже и небе.</p>\n<h2 id=\"filters-for-portraits\">Фильтры для портретов</h2>\n<p>Портретам подходят мягкие фильтры. «Винтаж», «Тёплый» и «Матовый» добавляют настроение, не меняя лица, а сильные фильтры могут сделать кожу неестественной.</p>\n<p>Избегайте «Высокого контраста» и «Драматичного» на портретах, если только настроение этого не требует. Сильные тени могут состарить лицо и сделать кожу жёсткой.</p>\n<p>«Ч/б Нуар» подходит портретам с сильными выражениями. Драматичное чёрно-белое фото подчёркивает глаза и эмоции, поэтому это классический фильтр для портретов.</p>\n<p>Проверяйте тона кожи после каждого фильтра. Фильтр, который хорошо выглядит на фоне, может сделать лицо оранжевым, зелёным или серым, поэтому всегда проверяйте человека первым.</p>\n<h2 id=\"filters-for-landscapes\">Фильтры для пейзажей</h2>\n<p>Пейзажам подходят более сильные фильтры. «Золотой час» добавляет тепла закату, «Драматичный» углубляет мрачное небо, а «Высокий контраст» добавляет энергии плоской сцене.</p>\n<p>«Винтаж» и «Матовый» подходят мягким, мечтательным пейзажам. Туманное утро или тихое поле приобретают нежное, ностальгическое ощущение от выцветшего фильтра.</p>\n<p>Избегайте «Холодного» на тёплом пейзаже. Закат с синим оттенком спорит с естественным теплом, и результат выглядит как ошибка, а не как стиль.</p>\n<p>Для пейзажа с ярким небом проверяйте облака после фильтрации. Сильный фильтр может выжечь света и превратить небо в белое пятно.</p>\n<h2 id=\"consistent-look\">Выбор единого вида</h2>\n<p>Единый фильтр для всех ваших фото создаёт узнаваемый стиль. Подписчики учатся узнавать вашу работу, не читая имя, и это выстраивает визуальную идентичность.</p>\n<p>Выберите один фильтр и одну интенсивность и используйте их для всей серии. Лента, где каждое фото имеет тот же «Винтаж» на 50 процентах, выглядит продуманной, а смешанные фильтры — случайными.</p>\n<p>Проверьте фильтр на разных типах фото, прежде чем остановиться на нём. Фильтр, который подходит пейзажам, может не подойти портретам, а единый вид нуждается в фильтре, который работает и там и там.</p>\n<p>Пересматривайте выбор фильтра время от времени. Стили меняются, и фильтр, который казался свежим в прошлом году, сейчас может казаться устаревшим, поэтому обновляйте его, когда ваша работа развивается.</p>\n<p>Меняйте фильтр осознанно, а не случайно: выберите дату, например начало года, и пересмотрите стиль всей ленты целиком. Резкая смена фильтра посреди серии выглядит как ошибка, а плановая — как новый этап.</p>\n<h2 id=\"formats-and-export\">Форматы и сохранение</h2>\n<p>Инструмент принимает распространённые форматы изображений, включая JPG, PNG, WebP и HEIC, с файлами до 20 МБ. Сохранять можно в JPG, PNG или WebP — в зависимости от ваших нужд.</p>\n<p>Сохранение в PNG или WebP сохраняет прозрачность исходного изображения. Если ваш исходник — прозрачный PNG-логотип, отфильтрованная копия сохранит сквозные области целыми, хотя большинство фильтров предназначены для фото.</p>\n<p>Для фото хорошо подходит JPG с высоким качеством. Фильтры почти не добавляют веса файлу, поэтому сохранённая копия остаётся близкой к оригиналу по размеру.</p>\n<p>Ползунок качества появляется при сохранении в JPG и WebP и скрывается для PNG, потому что PNG работает без потерь и настройки качества у него нет.</p>\n<h2 id=\"privacy-local-processing\">Конфиденциальность: фильтрация без загрузки на сервер</h2>\n<p>Вся работа с фильтрами происходит в вашем браузере. Фото никуда не загружаются, что важно, когда речь идёт о личных и семейных снимках или работе для клиентов.</p>\n<p>Это настоящее преимущество перед облачными редакторами. Семейное фото или личный портрет не должны отправляться на неизвестный сервер только ради добавления фильтра.</p>\n<p>Инструмент также удаляет GPS-данные EXIF при сохранении. В скачанном фото с фильтром не будет записи о том, где оно было сделано.</p>\n<p>Храните исходное фото без фильтра. Когда фильтр «впечатан» в сохранённый файл, убрать его из этого файла уже нельзя, поэтому оригинал — ваша единственная чистая копия.</p>\n<h2 id=\"common-mistakes\">Частые ошибки при использовании фильтров</h2>\n<p>Самая частая ошибка — использовать фильтр на полной интенсивности, когда меньшее значение было бы лучше. Фильтр «Винтаж» на 100 процентах может подавить фото, а тот же фильтр на 50 процентах добавляет настроение, не скрывая объект.</p>\n<p>Ещё одна ошибка — использовать разный фильтр на каждом фото. Лента со смешанными фильтрами выглядит случайно, а единый фильтр выстраивает узнаваемый стиль.</p>\n<p>Многие забывают проверять кожу. Фильтр, который хорошо выглядит на фоне, может сделать лицо оранжевым, зелёным или серым, поэтому всегда проверяйте человека первым.</p>\n<p>И наконец, не складывайте фильтры в инструменте. Инструмент применяет один фильтр за раз, а попытка наслоить их повторной загрузкой отфильтрованного изображения добавляет повреждения с каждым кругом.</p>\n<h2 id=\"filters-for-travel\">Фильтры для фото из путешествий</h2>\n<p>Фото из путешествий смешивают людей, пейзажи, еду и архитектуру, поэтому им нужен фильтр, который работает со всем. «Винтаж» на 50 процентах — безопасный выбор, ведь его мягкий вид подходит всем четырём.</p>\n<p>Используйте один фильтр для всей поездки, чтобы набор ощущался как одно путешествие. Альбом путешествия, где каждое фото имеет тот же фильтр, выглядит продуманным, а смешанные фильтры кажутся случайными.</p>\n<p>Проверяйте людей на каждом фото из путешествия после фильтрации. Фильтр для пейзажа, который хорошо выглядит на природе, может сделать путешественников оранжевыми, поэтому всегда проверяйте лица.</p>\n<p>Для ленты путешествия проверьте фильтр на нескольких пробных фото, прежде чем остановиться на нём. Фильтр, который подходит пляжу, может не подойти городской улице, а поездке нужен тот, что работает и там и там.</p>\n<p>Возьмите в поездку три пробных снимка — портрет, пейзаж и еду — и проверьте фильтр на них ещё до отъезда. Если один фильтр хорошо смотрится на всех трёх, он выдержит и всю поездку, какой бы разной она ни оказалась.</p>\n<p>Пошаговый процесс смотрите в статье <a href=\"/ru/blog/kak-primenit-filtr-k-foto/\">Как применить фильтр к фото</a>. Сравнение читайте в статье <a href=\"/ru/blog/sravnenie-filtrov-dlya-foto/\">Сравнение фильтров для фото: как выбрать единый стиль</a>, а чтобы настроить цвета точно вместо готового пресета, попробуйте <a href=\"/ru/izmenit-nasyshchennost-izobrazheniya/\">редактор насыщенности изображения</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Какой фильтр для фото лучше всего подходит портретам?","answer":"«Винтаж», «Тёплый» или «Матовый» при умеренной интенсивности около 50 процентов. Они добавляют настроение, не меняя лица. Избегайте «Высокого контраста» и «Драматичного» на портретах, если только настроение этого не требует, и всегда проверяйте тона кожи после применения фильтра."},{"question":"Что делает ползунок интенсивности фильтра?","answer":"Он управляет тем, насколько сильно применяется фильтр: от 0 процентов (исходное фото) до 100 процентов (полный эффект). Установка «Винтажа» на 45 процентов смешивает отфильтрованные пиксели обратно к оригиналу, давая лёгкую плёночную дымку, не подавляя естественные тона кожи."},{"question":"Почему инструмент запускается с выбранным «Винтажем»?","answer":"«Винтаж» на 100 процентах — значение по умолчанию, чтобы вы сразу после загрузки видели готовый эффект на основном холсте. Это мягкий, лестный фильтр, который подходит большинству фото. Нажмите на любую другую плитку, чтобы переключиться, или «Сброс», чтобы вернуться к оригиналу."},{"question":"Можно ли применить два фильтра к одному фото?","answer":"Не за один шаг: инструмент применяет один фильтр за раз. Повторная загрузка отфильтрованного изображения для добавления второго фильтра возможна, но добавляет повреждения с каждым кругом. Выберите один фильтр, который лучше всего соответствует нужному виду, и настройте его интенсивность."},{"question":"Меняют ли фильтры разрешение фото?","answer":"Нет. Фильтры меняют цвета, контраст и тон, но размеры в пикселях остаются прежними. Миниатюры предпросмотра маленькие, но скачанный файл обрабатывается в полном разрешении, поэтому сохранённая копия сохраняет исходный размер."},{"question":"Безопасно ли применять фильтры к личному фото в браузерном инструменте?","answer":"Да, потому что вся обработка происходит локально в вашем браузере и ничего не загружается на сервер. Инструмент также удаляет GPS-данные EXIF при сохранении. Храните исходный файл, если хотите попробовать другой фильтр позже."}];
